import { useMutation } from '@tanstack/react-query';

import { queryKeys } from '@/helpers';
import { authentication } from '@/infrastructure';

/**
 * Submit the 6-digit TOTP code generated by the CFM MFA app.
 *
 * @example
 * const reqVerifyOTP = useVerifyOTP();
 * reqVerifyOTP.mutate({ otp: '123456' });
 */
export default function useVerifyOTP() {
  return useMutation({
    mutationKey: queryKeys.verifyOTP,
    mutationFn: authentication.verifyOTP,
  });
}
